# Sums the plate prices, using the default price for colors not in the list
n, m = map(int, input().split())
c = input().split()
d = input().split()
p = list(map(int, input().split()))
ds = {d[i]: p[1 + i] for i in range(m)}
s = 0
for i in c:
    if i not in ds:
        s += p[0]
    else:
        s += ds[i]
print(s)

